"""Bounded ZIP decoder for CI-generated byte fixtures ONLY.

No paths, extraction, filesystem, subprocesses, network, IPC or real mods.
This is not a production-safe reader of untrusted user archives.
"""
from __future__ import annotations
import io
import re
import stat
import zipfile

MAX_ARCHIVE_BYTES = 2_000_000
MAX_EXPANDED_BYTES = 4_000_000
MAX_ENTRIES = 128
MAX_ENTRY_PATH = 160
MAX_DEPTH = 12
MAX_RATIO = 100
CHUNK = 16_384
# Fixed output schema. These are filename SUFFIXES only, never parsed format
# evidence or an identification of the target simulator.
SUFFIXES = (
    "bus", "cfg", "sco", "sli", "sii", "scs", "dds",
    "png", "jpg", "wav", "ogg", "bank", "json", "other"
)
VALID_NAME = re.compile(r"[A-Za-z0-9_./-]+\Z", re.ASCII)
RESERVED = re.compile(r"(?:con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\..*)?\Z", re.IGNORECASE)

class ControlledZipRefused(ValueError):
    pass

def refuse():
    raise ControlledZipRefused("CONTROLLED_ZIP_BYTES_REFUSED")

def examine_controlled_zip_bytes(payload: bytes) -> dict:
    """Return only aggregate measurements and explicit negative assurances."""
    if type(payload) is not bytes or not (0 < len(payload) <= MAX_ARCHIVE_BYTES):
        refuse()
    declared = actual = files = dirs = 0
    seen: set[str] = set()
    file_names: set[str] = set()
    suffix_counts = {suffix: 0 for suffix in SUFFIXES}
    try:
        with zipfile.ZipFile(io.BytesIO(payload)) as zf:
            infos = zf.infolist()
            if len(infos) > MAX_ENTRIES:
                refuse()
            for info in infos:
                name = info.filename
                if (not name or len(name) > MAX_ENTRY_PATH or
                    not VALID_NAME.fullmatch(name) or name.startswith("/") or
                    "\\" in name or "//" in name or ":" in name):
                    refuse()
                is_dir = info.is_dir()
                parts = name.rstrip("/").split("/")
                if len(parts) > MAX_DEPTH or any(
                    not part or part in (".", "..") or part.endswith(".") or
                    RESERVED.fullmatch(part) for part in parts
                ):
                    refuse()
                normalized = "/".join(parts).lower()
                if normalized in seen:
                    refuse()
                seen.add(normalized)
                kind = stat.S_IFMT(info.external_attr >> 16)
                if kind not in (0, stat.S_IFDIR if is_dir else stat.S_IFREG):
                    refuse()
                if info.flag_bits & 1 or info.compress_type not in (
                    zipfile.ZIP_STORED, zipfile.ZIP_DEFLATED
                ):
                    refuse()
                if info.file_size < 0 or info.compress_size < 0:
                    refuse()
                if is_dir:
                    if info.file_size != 0 or info.compress_size != 0:
                        refuse()
                    dirs += 1
                    continue
                if (info.file_size > MAX_EXPANDED_BYTES or
                    (info.file_size > 0 and info.compress_size == 0) or
                    info.file_size > info.compress_size * MAX_RATIO):
                    refuse()
                declared += info.file_size
                if declared > MAX_EXPANDED_BYTES:
                    refuse()
                file_names.add(normalized)
                # Only an aggregate count derived from a *declared filename*.
                # Never expose names, roots, original case or full paths.
                last = parts[-1].lower()
                extension = last.rsplit(".", 1)[-1] if "." in last else ""
                suffix_counts[extension if extension in suffix_counts else "other"] += 1
                files += 1
            for name in seen:
                parts = name.split("/")
                if any("/".join(parts[:i]) in file_names for i in range(1, len(parts))):
                    refuse()
            # Read every entry to verify actual DEFLATE data and CRC,
            # with hard output accounting; no extraction to filesystem.
            for info in infos:
                if info.is_dir():
                    continue
                per_file = 0
                with zf.open(info) as source:
                    while True:
                        chunk = source.read(CHUNK)
                        if not chunk:
                            break
                        per_file += len(chunk)
                        actual += len(chunk)
                        if per_file > info.file_size or actual > MAX_EXPANDED_BYTES:
                            refuse()
                if per_file != info.file_size:
                    refuse()
    except (zipfile.BadZipFile, zipfile.LargeZipFile, RuntimeError,
            EOFError, OSError, NotImplementedError, OverflowError,
            MemoryError):
        refuse()
    return {
        "source": "ci-generated-zip-bytes",
        "fileCount": files,
        "directoryCount": dirs,
        "actualInflatedBytes": actual,
        "zipHeadersAndCrcRead": True,
        "declaredSuffixCounts": suffix_counts,
        "declaredSuffixesAreContentProof": False,
        "archiveOriginVerified": False,
        "gameRecognized": False,
        "compatibilityVerified": False,
        "installationEnabled": False,
        "realGameFilesTouched": False,
    }
